import{_ as n,y as s,a,o as i,a2 as r,D as o,g as l}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Content","description":"","frontmatter":{},"headers":[],"relativePath":"configure/content.md","filePath":"configure/content.md","lastUpdated":1789395222000}'),c={name:"configure/content.md"};function g(p,e,h,d,u,f){const t=s("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=r('<h1 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h1><p>The <strong>Content</strong> screen holds the promotional line at the top of the storefront, the copyright line in its footer, the speculation rules that make pages open faster, and your own CSS and JavaScript.</p><p>Go to <strong>Configure &gt;&gt; General &gt;&gt; Content</strong>.</p><h2 id="header-offer-title" tabindex="-1">Header offer title <a class="header-anchor" href="#header-offer-title" aria-label="Permalink to &quot;Header offer title&quot;">​</a></h2><p>The header offer is a short promotional line with a link, shown in the bar at the top of every storefront page.</p><ol><li>In <strong>Header Offer Title</strong>, enter the <strong>Offer Title</strong>, such as <code>Get UPTO 40% OFF on your 1st order</code>. It can be up to 100 characters.</li><li>Enter the <strong>Redirection Title</strong>, the link text shown after the offer, such as <code>SHOP NOW</code>. It can be up to 25 characters.</li><li>Enter the <strong>Redirection Link</strong>, the page the link opens, such as <code>/womens</code>. If you leave it empty, the link opens the home page.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',6)),o(t,{src:"/images/configure/content-header-offer.png",alt:"Header Offer Title and Copyright Content sections of the Content screen"}),o(t,{src:"/images/configure/content-header-offer-storefront.png",alt:"Header offer line in the top bar of the storefront"}),e[1]||(e[1]=r('<h2 id="copyright-content" tabindex="-1">Copyright content <a class="header-anchor" href="#copyright-content" aria-label="Permalink to &quot;Copyright content&quot;">​</a></h2><p>The copyright line is shown at the bottom of the storefront footer.</p><ol><li>In <strong>Copyright Content</strong>, enter the text, such as <code>© 2026 Example Store. All rights reserved.</code></li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The copyright line is set per language, so choose the language at the top of the screen to translate it. If you leave it empty, the storefront shows its default copyright line.</p>',4)),o(t,{src:"/images/configure/content-copyright-storefront.png",alt:"Copyright line at the bottom of the storefront footer"}),e[2]||(e[2]=r('<h2 id="speculation-rules" tabindex="-1">Speculation rules <a class="header-anchor" href="#speculation-rules" aria-label="Permalink to &quot;Speculation rules&quot;">​</a></h2><p>Speculation rules let a shopper&#39;s browser load a page before the shopper opens it, such as a link they are about to click, so the page appears almost instantly. They are off by default, because loading pages in advance uses bandwidth and shows up as visits to pages that were never opened.</p><ol><li>In <strong>Speculation Rules</strong>, switch <strong>Enable Speculation Rules</strong> on.</li><li>Switch on <strong>Enable Prerender Speculation Rules</strong>, <strong>Enable Prefetch Speculation Rules</strong>, or both. The settings for each appear below its switch.</li><li>Adjust the settings described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),o(t,{src:"/images/configure/content-speculation-rules.png",alt:"Speculation Rules section with prerender and prefetch turned on"}),e[3]||(e[3]=r('<p><strong>Enable Prerender Speculation Rules:</strong> Prerendering loads and displays the whole page in the background, so it appears instantly. It uses the most resources.</p><p><strong>Enable Prefetch Speculation Rules:</strong> Prefetching downloads the page in advance without displaying it. It uses fewer resources than prerendering.</p><p><strong>Ignore Prerender URLs</strong> and <strong>Ignore Prefetch URLs:</strong> Pages that are never loaded in advance, separated by a pipe (<code>|</code>). The default, <code>/customer/account/*|/checkout/*</code>, leaves out the customer account and checkout pages.</p><p><strong>Ignore Prerender URL Parameters</strong> and <strong>Ignore Prefetch URL Parameters:</strong> URL parameters to ignore, separated by a pipe (<code>|</code>), such as <code>ref|utm_source</code>.</p><p><strong>Prerender Eagerness Level</strong> and <strong>Prefetch Eagerness Level:</strong> How eagerly pages are loaded in advance. <strong>Eager</strong> loads the most, <strong>Moderate</strong> is the default, and <strong>Conservative</strong> loads the least.</p><h2 id="custom-scripts" tabindex="-1">Custom scripts <a class="header-anchor" href="#custom-scripts" aria-label="Permalink to &quot;Custom scripts&quot;">​</a></h2><p>Custom scripts add your own CSS and JavaScript to every storefront page of a channel without changing the theme, for example a color change, a chat widget or an analytics snippet.</p><ol><li>In <strong>Custom Scripts</strong>, enter your styles in <strong>Custom CSS</strong>. Don&#39;t include <code>&lt;style&gt;</code> tags; the store adds them.</li><li>Enter your script in <strong>Custom Javascript</strong>. Don&#39;t include <code>&lt;script&gt;</code> tags; the store adds them.</li><li>Click <strong>Save Configuration</strong>.</li><li>Reload the storefront to check the result.</li></ol>',8)),o(t,{src:"/images/configure/content-custom-scripts.png",alt:"Custom Scripts section with sample CSS and JavaScript"}),e[4]||(e[4]=l("p",null,"Both fields are set per channel. A script with an error can break every storefront page, so test it on a staging store first if you have one.",-1))])}const S=n(c,[["render",g]]);export{_ as __pageData,S as default};
